        "description": "3、轻资本运营与资产证券化出表：大力拓展不占用核心资本的投行中收业务。通过主导发行供应链ABS，供票ABN以及公募REITs顾问等服务，形成规模化的信贷资产出口。有效盘活全行存量信贷资产，大幅提升资本使用效率与核心ROE水平。",
