        "title": "1、平台向生态枢纽转型与跨部门协同：重构“黄海之链”底层架构，优化标准化，模块化的对外API接口，丰富保理，商票，订单融资等产品矩阵，实现系统级即插即用。深度配合大公司板块协同委员会，联合票据中心，交易银行创新推出“供应链+票据池”“供应链+国内证”等跨界融合的低风险高频产品。",
        "description": "1、平台向生态枢纽转型与跨部门协同：重构“黄海之链”底层架构，优化标准化，模块化的对外API接口，丰富保理，商票，订单融资等产品矩阵，实现系统级即插即用。深度配合大公司板块协同委员会，联合票据中心，交易银行创新推出“供应链+票据池”“供应链+国内证”等跨界融合的低风险高频产品。",
